import { NextResponse } from "next/server";
import type { SupabaseSessionResponse } from "@/platform/persistence/supabase-rest";

const secure = process.env.NODE_ENV === "production";

export function setStoryAuthCookies(response: NextResponse, session: SupabaseSessionResponse) {
  const accessMaxAge = Math.max(60, Math.min(session.expires_in || 3600, 60 * 60 * 24));
  response.cookies.set("story_access_token", session.access_token, { httpOnly: true, secure, sameSite: "lax", path: "/", maxAge: accessMaxAge });
  if (session.refresh_token) response.cookies.set("story_refresh_token", session.refresh_token, { httpOnly: true, secure, sameSite: "lax", path: "/", maxAge: 60 * 60 * 24 * 30 });
  return response;
}

export function clearStoryAuthCookies(response: NextResponse) {
  response.cookies.set("story_access_token", "", { httpOnly: true, secure, sameSite: "lax", path: "/", maxAge: 0 });
  response.cookies.set("story_refresh_token", "", { httpOnly: true, secure, sameSite: "lax", path: "/", maxAge: 0 });
  return response;
}

import { cookies } from "next/headers";
import { getSupabaseUser, refreshSupabaseSession } from "@/platform/persistence/supabase-rest";

export async function getStorySession() {
  const store = await cookies();
  const token = store.get("story_access_token")?.value ?? null;
  if (token) {
    try {
      const user = await getSupabaseUser(token);
      return { token, user };
    } catch {
      // Fall through to refresh if available.
    }
  }

  const refreshToken = store.get("story_refresh_token")?.value ?? null;
  if (!refreshToken) return null;
  try {
    const refreshed = await refreshSupabaseSession(refreshToken);
    const user = refreshed.user ?? await getSupabaseUser(refreshed.access_token);
    try {
      store.set("story_access_token", refreshed.access_token, { httpOnly: true, secure: process.env.NODE_ENV === "production", sameSite: "lax", path: "/", maxAge: Math.max(60, refreshed.expires_in || 3600) });
      if (refreshed.refresh_token) store.set("story_refresh_token", refreshed.refresh_token, { httpOnly: true, secure: process.env.NODE_ENV === "production", sameSite: "lax", path: "/", maxAge: 60 * 60 * 24 * 30 });
    } catch {
      // Server Components may not be able to mutate cookies; the current request can still continue safely.
    }
    return { token: refreshed.access_token, user };
  } catch {
    return null;
  }
}

export async function requireStorySession() {
  const session = await getStorySession();
  if (!session) throw new Error("AUTH_REQUIRED");
  return session;
}

export async function isStoryAdmin() {
  const session = await getStorySession();
  if (!session) return false;
  return session.user.app_metadata?.role === "admin" || session.user.app_metadata?.admin === true;
}

import type { ChatImporter, ImportInput } from "./types";
import { telegramJsonImporter } from "./telegram";
import { whatsappTextImporter } from "./whatsapp";

export const chatImporters: ChatImporter[] = [telegramJsonImporter, whatsappTextImporter];

export function getChatImporter(input: Pick<ImportInput, "name" | "type">) {
  return chatImporters.find((importer) => importer.canHandle(input)) ?? null;
}

import { analyzeChat } from "@/lib/analyze";
import { MIN_CHAT_MESSAGES, tooFewMessagesError } from "@/lib/import-validation";
import type { ChatMessage } from "@/lib/types";
import { toThreadTaleResultV2 } from "@/platform/threadtales/result-v2";
import type { ChatImporter } from "./types";

type TelegramTextPart = string | { text?: string };
type TelegramMessage = { type?: string; date?: string; from?: string; actor?: string; text?: string | TelegramTextPart[]; media_type?: string; photo?: string; file?: string };
type TelegramChat = { name?: string; messages?: TelegramMessage[] };
type TelegramExport = { messages?: TelegramMessage[]; chats?: { list?: TelegramChat[] } };

function textOf(value: TelegramMessage["text"]) {
  if (typeof value === "string") return value;
  if (!Array.isArray(value)) return "";
  return value.map((part) => typeof part === "string" ? part : part.text ?? "").join("");
}

function selectMessages(root: TelegramExport) {
  if (Array.isArray(root.messages)) return root.messages;
  const chats = root.chats?.list?.filter((chat) => Array.isArray(chat.messages)) ?? [];
  if (chats.length === 1) return chats[0].messages ?? [];
  if (chats.length > 1) throw new Error("This Telegram export contains multiple chats. Export or select one chat as JSON so ThreadTales does not combine unrelated conversations.");
  throw new Error("I couldn't find a Telegram message list in this JSON export.");
}

export const telegramJsonImporter: ChatImporter = {
  id: "telegram-json",
  label: "Telegram JSON chat export",
  canHandle(input) { return input.name.toLowerCase().endsWith(".json") || input.type === "application/json"; },
  async parse(input) {
    let root: TelegramExport;
    try { root = JSON.parse(input.text) as TelegramExport; }
    catch { throw new Error("That .json file is not valid Telegram JSON."); }
    const messages: ChatMessage[] = [];
    for (const message of selectMessages(root)) {
      if (message.type && message.type !== "message") continue;
      const timestamp = Date.parse(message.date ?? "");
      if (!Number.isFinite(timestamp)) continue;
      const sender = (message.from ?? message.actor ?? "Unknown").trim();
      const body = textOf(message.text).trim() || (message.media_type || message.photo || message.file ? "<Media omitted>" : "");
      if (!sender || !body) continue;
      messages.push({ sender, timestamp, text: body });
    }
    messages.sort((a, b) => a.timestamp - b.timestamp);
    if (messages.length < MIN_CHAT_MESSAGES) throw new Error(tooFewMessagesError(messages.length));
    const stats = analyzeChat(messages);
    return { messages, stats, result: toThreadTaleResultV2(stats, "telegram"), warnings: ["Telegram JSON was parsed locally. Message text remains browser-only in the free flow."] };
  },
};

import type { ChatMessage, ChatStats, DateOrder } from "@/lib/types";
import type { ThreadTaleResultV2 } from "@/platform/types";

export interface ImportInput {
  name: string;
  type?: string;
  size?: number;
  text: string;
}

export interface ParseOptions {
  dateOrder: DateOrder;
}

export interface ParseResult {
  messages: ChatMessage[];
  stats: ChatStats;
  result: ThreadTaleResultV2;
  warnings: string[];
}

export interface ChatImporter {
  id: string;
  label: string;
  canHandle(input: Pick<ImportInput, "name" | "type">): boolean;
  parse(input: ImportInput, options: ParseOptions): Promise<ParseResult>;
}

import { analyzeChat } from "@/lib/analyze";
import { MIN_CHAT_MESSAGES, tooFewMessagesError } from "@/lib/import-validation";
import { parseChat } from "@/lib/parser";
import { toThreadTaleResultV2 } from "@/platform/threadtales/result-v2";
import type { ChatImporter } from "./types";

export const whatsappTextImporter: ChatImporter = {
  id: "whatsapp-text",
  label: "WhatsApp text export",
  canHandle(input) {
    return input.name.toLowerCase().endsWith(".txt") || input.type === "text/plain";
  },
  async parse(input, options) {
    const messages = parseChat(input.text, options.dateOrder);
    if (messages.length < MIN_CHAT_MESSAGES) throw new Error(tooFewMessagesError(messages.length));
    const stats = analyzeChat(messages);
    return {
      messages,
      stats,
      result: toThreadTaleResultV2(stats, "whatsapp"),
      warnings: options.dateOrder === "auto" ? ["Ambiguous numeric dates are interpreted US-first. Change the date selector if the timeline looks wrong."] : [],
    };
  },
};

export interface LocalMediaAsset {
  id: string;
  name: string;
  type: string;
  size: number;
  lastModified: number;
  objectUrl: string;
}

export interface MediaStorageAdapter {
  upload(asset: File, context: { product: "myyear" | "petlife"; ownerId: string }): Promise<{ id: string; privateUrl?: string }>;
  remove(id: string): Promise<void>;
}

export function createLocalMediaAssets(files: FileList | File[] | null | undefined, limit = 12): LocalMediaAsset[] {
  if (!files) return [];
  return Array.from(files).slice(0, Math.max(0, limit)).filter((file) => file.type.startsWith("image/")).map((file, index) => ({
    id: `${file.name}-${file.lastModified}-${file.size}-${index}`,
    name: file.name,
    type: file.type || "image/*",
    size: file.size,
    lastModified: file.lastModified,
    objectUrl: URL.createObjectURL(file),
  }));
}

export function revokeLocalMediaAssets(assets: LocalMediaAsset[]) {
  for (const asset of assets) URL.revokeObjectURL(asset.objectUrl);
}

export function mediaMetadataOnly(assets: LocalMediaAsset[]) {
  return assets.map(({ name, type, size, lastModified }) => ({ name, type, size, lastModified }));
}

export function getSupabasePublicConfig() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL?.replace(/\/$/, "");
  const publishableKey = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
  if (!url || !publishableKey) return null;
  return { url, publishableKey };
}

export function requireSupabasePublicConfig() {
  const config = getSupabasePublicConfig();
  if (!config) throw new Error("Supabase persistence is not configured.");
  return config;
}

export function requireSupabaseSecretConfig() {
  const publicConfig = requireSupabasePublicConfig();
  const secretKey = process.env.SUPABASE_SECRET_KEY;
  if (!secretKey) throw new Error("Supabase server persistence is not configured.");
  return { ...publicConfig, secretKey };
}

export function isSupabaseConfigured() {
  return Boolean(getSupabasePublicConfig());
}

export function isSupabaseServerConfigured() {
  return Boolean(getSupabasePublicConfig() && process.env.SUPABASE_SECRET_KEY);
}

import { requireSupabasePublicConfig, requireSupabaseSecretConfig } from "./config";

export interface SupabaseSessionResponse {
  access_token: string;
  refresh_token: string;
  expires_in: number;
  expires_at?: number;
  user?: { id: string; email?: string; user_metadata?: Record<string, unknown>; app_metadata?: Record<string, unknown> };
}

type AuthErrorShape = { msg?: string; message?: string; error_description?: string; error?: string };

async function authFetch<T>(path: string, init: RequestInit = {}) {
  const { url, publishableKey } = requireSupabasePublicConfig();
  const response = await fetch(`${url}/auth/v1${path}`, {
    ...init,
    headers: {
      apikey: publishableKey,
      "Content-Type": "application/json",
      ...(init.headers ?? {}),
    },
    cache: "no-store",
  });
  const data = await response.json().catch(() => ({})) as T & AuthErrorShape;
  if (!response.ok) throw new Error(data.msg ?? data.message ?? data.error_description ?? data.error ?? "Supabase Auth request failed.");
  return data;
}

function normalizeEmail(email: string) {
  const normalized = email.trim().toLowerCase();
  if (!/^\S+@\S+\.\S+$/.test(normalized) || normalized.length > 254) throw new Error("Enter a valid email address.");
  return normalized;
}

function assertPassword(password: string) {
  if (password.length < 10 || password.length > 128) throw new Error("Use a password between 10 and 128 characters.");
  if (!/[A-Za-z]/.test(password) || !/\d/.test(password)) throw new Error("Use at least one letter and one number.");
}

export function signUpWithPassword(email: string, password: string, displayName: string, redirectTo: string) {
  assertPassword(password);
  const name = displayName.trim().slice(0, 80);
  if (name.length < 2) throw new Error("Add your display name.");
  const query = new URLSearchParams({ redirect_to: redirectTo });
  return authFetch<SupabaseSessionResponse>(`/signup?${query.toString()}`, {
    method: "POST",
    body: JSON.stringify({ email: normalizeEmail(email), password, data: { display_name: name } }),
  });
}

export function signInWithPassword(email: string, password: string) {
  if (!password) throw new Error("Password is required.");
  return authFetch<SupabaseSessionResponse>("/token?grant_type=password", {
    method: "POST",
    body: JSON.stringify({ email: normalizeEmail(email), password }),
  });
}

export function refreshSupabaseSession(refreshToken: string) {
  if (!refreshToken || refreshToken.length > 4096) throw new Error("Invalid refresh token.");
  return authFetch<SupabaseSessionResponse>("/token?grant_type=refresh_token", {
    method: "POST",
    body: JSON.stringify({ refresh_token: refreshToken }),
  });
}

export function sendMagicLink(email: string, redirectTo: string) {
  const query = new URLSearchParams({ redirect_to: redirectTo });
  return authFetch<Record<string, never>>(`/otp?${query.toString()}`, {
    method: "POST",
    body: JSON.stringify({ email: normalizeEmail(email), create_user: false }),
  });
}

export function sendPasswordRecovery(email: string, redirectTo: string) {
  const query = new URLSearchParams({ redirect_to: redirectTo });
  return authFetch<Record<string, never>>(`/recover?${query.toString()}`, {
    method: "POST",
    body: JSON.stringify({ email: normalizeEmail(email) }),
  });
}

export function verifyAuthToken(tokenHash: string, type: "email" | "signup" | "recovery" | "magiclink") {
  if (!/^[A-Za-z0-9_-]{20,512}$/.test(tokenHash)) throw new Error("Invalid authentication token.");
  return authFetch<SupabaseSessionResponse>("/verify", {
    method: "POST",
    body: JSON.stringify({ token_hash: tokenHash, type }),
  });
}

export function verifyMagicLinkToken(tokenHash: string) {
  return verifyAuthToken(tokenHash, "email");
}

export function updateSupabasePassword(accessToken: string, password: string) {
  assertPassword(password);
  return authFetch<{ id: string; email?: string }>("/user", {
    method: "PUT",
    headers: { Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({ password }),
  });
}

export async function getSupabaseUser(accessToken: string) {
  return authFetch<{ id: string; email?: string; user_metadata?: Record<string, unknown>; app_metadata?: Record<string, unknown>; last_sign_in_at?: string; created_at?: string }>("/user", {
    method: "GET",
    headers: { Authorization: `Bearer ${accessToken}` },
  });
}

export async function supabaseRest<T>(tableAndQuery: string, accessToken: string, init: RequestInit = {}) {
  const { url, publishableKey } = requireSupabasePublicConfig();
  const response = await fetch(`${url}/rest/v1/${tableAndQuery}`, {
    ...init,
    headers: {
      apikey: publishableKey,
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      ...(init.headers ?? {}),
    },
    cache: "no-store",
  });
  if (response.status === 204) return null as T;
  const data = await response.json().catch(() => null) as T | { message?: string; details?: string } | null;
  if (!response.ok) {
    const error = data as { message?: string; details?: string } | null;
    throw new Error(error?.message ?? error?.details ?? "Supabase Data API request failed.");
  }
  return data as T;
}

export async function supabaseAdminRest<T>(tableAndQuery: string, init: RequestInit = {}) {
  const { url, secretKey } = requireSupabaseSecretConfig();
  const response = await fetch(`${url}/rest/v1/${tableAndQuery}`, {
    ...init,
    headers: {
      apikey: secretKey,
      Authorization: `Bearer ${secretKey}`,
      "Content-Type": "application/json",
      ...(init.headers ?? {}),
    },
    cache: "no-store",
  });
  if (response.status === 204) return null as T;
  const data = await response.json().catch(() => null) as T | { message?: string; details?: string } | null;
  if (!response.ok) {
    const error = data as { message?: string; details?: string } | null;
    throw new Error(error?.message ?? error?.details ?? "Supabase admin request failed.");
  }
  return data as T;
}

export async function supabaseStorageUpload(path: string, file: Blob, accessToken: string, contentType: string) {
  const { url, publishableKey } = requireSupabasePublicConfig();
  const response = await fetch(`${url}/storage/v1/object/private-media/${path.split("/").map(encodeURIComponent).join("/")}`, {
    method: "POST",
    headers: {
      apikey: publishableKey,
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": contentType,
      "x-upsert": "false",
    },
    body: file,
  });
  const data = await response.json().catch(() => ({})) as { Key?: string; key?: string; message?: string };
  if (!response.ok) throw new Error(data.message ?? "Media upload failed.");
  return data;
}

export async function supabaseStorageSignedUrl(path: string, accessToken: string, expiresIn = 900) {
  const { url, publishableKey } = requireSupabasePublicConfig();
  const encoded = path.split("/").map(encodeURIComponent).join("/");
  const response = await fetch(`${url}/storage/v1/object/sign/private-media/${encoded}`, {
    method: "POST",
    headers: { apikey: publishableKey, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
    body: JSON.stringify({ expiresIn: Math.max(60, Math.min(expiresIn, 3600)) }),
  });
  const data = await response.json().catch(() => ({})) as { signedURL?: string; signedUrl?: string; message?: string };
  if (!response.ok) throw new Error(data.message ?? "Could not create media URL.");
  const signedPath = data.signedURL ?? data.signedUrl;
  if (!signedPath) throw new Error("Supabase did not return a signed media URL.");
  return signedPath.startsWith("http") ? signedPath : `${url}/storage/v1${signedPath.startsWith("/") ? signedPath : `/${signedPath}`}`;
}

export async function supabaseStorageDelete(path: string, accessToken: string) {
  const { url, publishableKey } = requireSupabasePublicConfig();
  const encoded = path.split("/").map(encodeURIComponent).join("/");
  const response = await fetch(`${url}/storage/v1/object/private-media/${encoded}`, {
    method: "DELETE",
    headers: { apikey: publishableKey, Authorization: `Bearer ${accessToken}` },
  });
  if (!response.ok && response.status !== 404) {
    const data = await response.json().catch(() => ({})) as { message?: string };
    throw new Error(data.message ?? "Media delete failed.");
  }
}

const RAW_CONTENT_KEYS = new Set([
  "raw", "rawtext", "rawchat", "messages", "chatmessages", "messagetext", "sender", "transcript", "conversation", "text",
]);

export function assertDerivedStoryPayload(value: unknown) {
  const visit = (node: unknown, depth: number) => {
    if (depth > 20) throw new Error("Story payload is too deeply nested.");
    if (!node || typeof node !== "object") return;
    if (Array.isArray(node)) {
      if (node.length > 5000) throw new Error("Story payload is too large to save.");
      node.forEach((item) => visit(item, depth + 1));
      return;
    }
    const record = node as Record<string, unknown>;
    if ("sender" in record && "timestamp" in record && "text" in record) throw new Error("Raw chat messages cannot be saved to cloud persistence.");
    for (const [key, child] of Object.entries(record)) {
      const normalizedKey = key.replace(/[_\-\s]/g, "").toLowerCase();
      if (RAW_CONTENT_KEYS.has(normalizedKey)) throw new Error(`Cloud save rejected a raw-content field: ${key}`);
      visit(child, depth + 1);
    }
  };
  visit(value, 0);
}

import type { ChatStats, StoryMode } from "@/lib/types";
import type { PrintBookSpec } from "@/platform/types";
import { composeThreadTale } from "@/platform/story/compose";
import { getStoryModeConfig } from "@/platform/story/modes";

const PRINT_SPECS = { "6x9": { width: 6, height: 9, maxBleed: 0.25 }, "8x10": { width: 8, height: 10, maxBleed: 0.25 } } as const;

export function buildThreadTaleBookSpec(stats: ChatStats, mode: StoryMode, options: { title?: string; subtitle?: string; dedication?: string; trimSize?: PrintBookSpec["trimSize"]; bleed?: number } = {}): PrintBookSpec {
  const trimSize = options.trimSize ?? "6x9"; const bleed = options.bleed ?? 0.125; validatePrintSettings(trimSize, bleed); const config = getStoryModeConfig(mode); const chapters = composeThreadTale(stats, mode); const pages: PrintBookSpec["pages"] = [];
  if (options.dedication?.trim()) pages.push({ id: "dedication", kind: "dedication", title: "For you", body: options.dedication.trim().slice(0, 1200) });
  for (const chapter of chapters) pages.push({ id: chapter.id, kind: chapter.type === "cover" ? "cover" : chapter.type === "timeline" ? "timeline" : chapter.type === "closing" ? "ending" : "chapter", title: chapter.title, body: chapter.supportingText, metric: chapter.metric });
  return { trimSize, bleed, cover: { title: (options.title?.trim() || config.eyebrow).slice(0, 160), subtitle: (options.subtitle?.trim() || `${stats.totalMessages.toLocaleString()} messages · ${stats.daysTogether.toLocaleString()} days`).slice(0, 220) }, pages };
}

export function validatePrintSettings(trimSize: PrintBookSpec["trimSize"], bleed: number) { const spec = PRINT_SPECS[trimSize]; if (!spec) throw new Error("Unsupported print trim size."); if (!Number.isFinite(bleed) || bleed < 0 || bleed > spec.maxBleed) throw new Error(`Bleed must be between 0 and ${spec.maxBleed} inches.`); return { ...spec, bleed }; }

import type { ChatStats, StoryMode } from "@/lib/types";
import type { StoryChapter, ThreadTaleShareManifest } from "@/platform/types";
import { getStoryModeConfig } from "./modes";

function number(value: number) {
  return new Intl.NumberFormat("en").format(value);
}

function date(timestamp: number) {
  return new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date(timestamp));
}

function hour(value: number) {
  const suffix = value >= 12 ? "pm" : "am";
  return `${value % 12 || 12}:00${suffix}`;
}

function replyLabel(minutes: number | null) {
  if (minutes === null) return null;
  if (minutes < 1) return "under a minute";
  if (minutes < 60) return `${Math.round(minutes)} min`;
  if (minutes < 24 * 60) return `${(minutes / 60).toFixed(minutes >= 600 ? 0 : 1)} hr`;
  return `${(minutes / (24 * 60)).toFixed(1)} days`;
}

function strongestResponseBucket(stats: ChatStats) {
  const buckets = [
    { label: "under 5 minutes", value: stats.responseGaps.under5Minutes },
    { label: "5–30 minutes", value: stats.responseGaps.under30Minutes },
    { label: "30 minutes–2 hours", value: stats.responseGaps.under2Hours },
    { label: "2–12 hours", value: stats.responseGaps.under12Hours },
    { label: "over 12 hours", value: stats.responseGaps.over12Hours },
  ];
  return buckets.sort((a, b) => b.value - a.value)[0];
}

function strongestVibe(stats: ChatStats) {
  const vibes = [
    { label: "Night owl", value: stats.vibe.nightOwl },
    { label: "Curious", value: stats.vibe.curiosity },
    { label: "Chaotic", value: stats.vibe.chaos },
    { label: "Affectionate", value: stats.vibe.affection },
  ];
  return vibes.sort((a, b) => b.value - a.value)[0];
}

function makeChapter(type: StoryChapter["type"], stats: ChatStats, mode: StoryMode): StoryChapter | null {
  const config = getStoryModeConfig(mode);

  switch (type) {
    case "cover":
      return { id: "cover", type, title: config.eyebrow, subtitle: "A ThreadTale", supportingText: `${number(stats.daysTogether)} days of conversation`, privacyLevel: "safe", renderVariant: "hero" };
    case "beginning":
      return { id: "beginning", type, title: "This story starts here.", metric: date(stats.firstTimestamp), supportingText: `The first message in this export arrived in ${new Date(stats.firstTimestamp).getFullYear()}.`, privacyLevel: "safe", renderVariant: "metric" };
    case "scale":
      return { id: "scale", type, title: "Somehow, you sent all of these.", metric: number(stats.totalMessages), subtitle: "messages", supportingText: `${number(stats.totalWords)} meaningful words across ${number(stats.activeDays)} active days.`, privacyLevel: "safe", renderVariant: "metric" };
    case "balance": {
      const first = stats.participants[0];
      const second = stats.participants[1];
      if (!first || !second) return null;
      return { id: "balance", type, title: "Who carried the chat?", metric: `${first.percentage}% / ${second.percentage}%`, supportingText: `${first.name} and ${second.name} made this a ${Math.abs(first.percentage - second.percentage) <= 10 ? "surprisingly even" : "beautifully uneven"} conversation.`, privacyLevel: "sensitive", renderVariant: "split" };
    }
    case "conversation-starter": {
      const starter = [...stats.participants].sort((a, b) => b.conversationStarts - a.conversationStarts)[0];
      if (!starter || starter.conversationStarts < 1) return null;
      return { id: "conversation-starter", type, title: "Someone kept pressing start.", metric: starter.conversationStarts, subtitle: "conversation starts", supportingText: `${starter.name} started the most new chat sessions in this export.`, privacyLevel: "sensitive", renderVariant: "metric" };
    }
    case "reply-speed": {
      const label = replyLabel(stats.medianReplyMinutes);
      if (!label) return null;
      return { id: "reply-speed", type, title: "The chat usually came back around.", metric: label, subtitle: "median reply time", supportingText: "Measured only between consecutive messages from different senders.", privacyLevel: "safe", renderVariant: "metric" };
    }
    case "response-rhythm": {
      const bucket = strongestResponseBucket(stats);
      if (!bucket || bucket.value < 1) return null;
      return { id: "response-rhythm", type, title: "This was your most common reply rhythm.", metric: number(bucket.value), subtitle: `replies ${bucket.label}`, supportingText: "A descriptive timing pattern, not a relationship score.", privacyLevel: "safe", renderVariant: "metric" };
    }
    case "streak":
      return { id: "streak", type, title: "There was a stretch when nobody stopped talking.", metric: stats.longestStreak, subtitle: "days in a row", supportingText: stats.longestSilenceDays > 0 ? `The longest quiet spell between active days was ${stats.longestSilenceDays} days.` : "The chat barely took a day off.", privacyLevel: "safe", renderVariant: "metric" };
    case "busiest-day":
      return { id: "busiest-day", type, title: "This day got out of hand.", metric: number(stats.biggestDay.messages), subtitle: `messages on ${date(stats.biggestDay.timestamp)}`, privacyLevel: "safe", renderVariant: "metric" };
    case "late-night":
      return { id: "late-night", type, title: "Apparently sleep was optional.", metric: hour(stats.peakHour), subtitle: "peak chat hour", supportingText: `${number(stats.lateNightMessages)} messages landed between midnight and 5am.`, privacyLevel: "safe", renderVariant: "metric" };
    case "language": {
      const word = stats.topWords[0];
      return { id: "language", type, title: word ? "One word kept finding its way back." : "There was plenty of personality in the chat.", metric: word?.word ?? number(stats.laughSignals), subtitle: word ? `${number(word.count)} appearances` : "laugh signals", supportingText: `${number(stats.laughSignals)} laugh signals and ${number(stats.heartSignals)} heart signals made the trail.`, privacyLevel: word ? "sensitive" : "safe", renderVariant: "metric" };
    }
    case "vibe": {
      const vibe = strongestVibe(stats);
      if (!vibe) return null;
      return { id: "vibe", type, title: "The strongest observable signal in this chat", metric: `${vibe.value}/100`, subtitle: vibe.label, supportingText: "A transparent presentation score built from observable message patterns—not psychology or compatibility.", privacyLevel: "safe", renderVariant: "metric" };
    }
    case "timeline": {
      const peak = [...stats.byYear].sort((a, b) => b.messages - a.messages)[0];
      return { id: "timeline", type, title: "Every year had its own pace.", metric: peak ? `${peak.year}` : new Date(stats.lastTimestamp).getFullYear(), subtitle: peak ? `${number(peak.messages)} messages in the busiest year` : "your timeline", supportingText: `${stats.byYear.length} calendar ${stats.byYear.length === 1 ? "year" : "years"} appear in this export.`, privacyLevel: "safe", renderVariant: "timeline" };
    }
    case "closing":
      return { id: "closing", type, title: config.ending, subtitle: `${number(stats.totalMessages)} messages later.`, supportingText: "Made privately with ThreadTales.", privacyLevel: "safe", renderVariant: "closing" };
  }
}

export function composeThreadTale(stats: ChatStats, mode: StoryMode = "friends") {
  const config = getStoryModeConfig(mode);
  return config.chapterPriority.map((type) => makeChapter(type, stats, mode)).filter((chapter): chapter is StoryChapter => chapter !== null);
}

export function createStoryShareManifest(stats: ChatStats, mode: StoryMode, options: { includeSensitive?: boolean; attribution?: boolean } = {}): ThreadTaleShareManifest {
  const { includeSensitive = false, attribution = true } = options;
  const chapters = composeThreadTale(stats, mode).filter((chapter) => includeSensitive || chapter.privacyLevel === "safe");
  return { version: 1, mode, title: getStoryModeConfig(mode).eyebrow, cards: chapters.map(({ id, title, subtitle, metric, renderVariant }) => ({ id, title, subtitle, metric, renderVariant })), attribution };
}

